            "\u0645\u0646 \u0632\u0627\u0648\u064a\u0629 \u0631\u0648\u0627\u064a\u062a\u0647\u0627 \u0644\u0644\u062d\u062f\u064a\u062b \u0627\u0644\u0646\u0628\u0648\u064a \u0648\u062f\u0648\u0631\u0647\u0627 \u0641\u064a \u062d\u0641\u0638 \u0627\u0644\u0633\u0646\u0629\u060c "
            "\u0641\u0647\u064a \u0645\u0646 \u0623\u0643\u062b\u0631 \u0623\u0645\u0647\u0627\u062a \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0623\u062d\u0627\u062f\u064a\u062b\u060c \u0648\u0627\u0644\u0639\u0628\u0631\u0629 \u0641\u064a\u0647\u0627 "
            "\u0623\u0646 \u0627\u0644\u0645\u0631\u0623\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u0629 \u0634\u0631\u064a\u0643 \u0641\u064a \u0628\u0646\u0627\u0621 \u0627\u0644\u0623\u0645\u0629 \u0644\u0627 \u0645\u062c\u0631\u062f \u0634\u0627\u0647\u062f\u0629 "
